  if(s.facade)return buildFacade(d,W,H,total,layers);
  check(!s.glass || s.glass.includes(total),'Bu seri için geçerli paketler (mm) '+(s.glass||[]).join(', '));
  check(total<=(s.max||Infinity)&&total>=(s.min||0),'Cam paketi seri aralığı dışında.');
